'use strict';

// MODULES //

var tape = require( 'tape' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var randu = require( '@stdlib/random/base/randu' );
var roundf = require( '@stdlib/math/base/special/roundf' );
var powf = require( '@stdlib/math/base/special/powf' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isNegativeZerof = require( '@stdlib/math/base/assert/is-negative-zerof' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var cfloornf = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cfloornf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a `NaN` if provided a `NaN`', function test( t ) {
	var v;

	v = cfloornf( new Complex64( NaN, NaN ), 0 );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( NaN, 3.14 ), 0 );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), false, 'returns expected value' );

	v = cfloornf( new Complex64( 3.14, NaN ), 0 );
	t.strictEqual( isnanf( realf( v ) ), false, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( NaN, NaN ), NaN );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( 3.14, 3.14 ), NaN );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `NaNs` if provided `n = +-infinity`', function test( t ) {
	var v;

	v = cfloornf( new Complex64( 3.14, 3.14 ), PINF );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( 3.14, 3.14 ), NINF );
	t.strictEqual( isnanf( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isnanf( imagf( v ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-0` if provided `-0`', function test( t ) {
	var v;

	v = cfloornf( new Complex64( -0.0, -0.0 ), 0 );
	t.strictEqual( isNegativeZerof( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isNegativeZerof( imagf( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( -0.0, -0.0 ), -2 );
	t.strictEqual( isNegativeZerof( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isNegativeZerof( imagf( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( -0.0, -0.0 ), 2 );
	t.strictEqual( isNegativeZerof( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isNegativeZerof( imagf( v ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+0` if provided `+0`', function test( t ) {
	var v;

	v = cfloornf( new Complex64( +0.0, +0.0 ), 0 );
	t.strictEqual( isPositiveZerof( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( +0.0, +0.0 ), -2 );
	t.strictEqual( isPositiveZerof( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );

	v = cfloornf( new Complex64( +0.0, +0.0 ), 2 );
	t.strictEqual( isPositiveZerof( realf( v ) ), true, 'returns expected value' );
	t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );

	t.end();
});

tape( 'the function returns `+infinity` if provided `+infinity`', function test( t ) {
	var v;

	v = cfloornf( new Complex64( PINF, PINF ), 5 );
	t.strictEqual( realf( v ), PINF, 'returns expected value' );
	t.strictEqual( imagf( v ), PINF, 'returns expected value' );
	t.end();
});

tape( 'the function returns `-infinity` if provided `-infinity`', function test( t ) {
	var v;

	v = cfloornf( new Complex64( NINF, NINF ), -3 );
	t.strictEqual( realf( v ), NINF, 'returns expected value' );
	t.strictEqual( imagf( v ), NINF, 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding real and imaginary components to a desired number of decimals', function test( t ) {
	var v;

	v = cfloornf( new Complex64( -3.141592653589793, 3.141592653589793 ), -2 );
	t.strictEqual( realf( v ), f32( -3.15 ), 'returns expected value' );
	t.strictEqual( imagf( v ), f32( 3.14 ), 'returns expected value' );

	v = cfloornf( new Complex64( 3.141592653589793, -3.141592653589793 ), -2 );
	t.strictEqual( realf( v ), f32( 3.14 ), 'returns expected value' );
	t.strictEqual( imagf( v ), f32( -3.15 ), 'returns expected value' );

	v = cfloornf( new Complex64( 9.99999, 9.99999 ), -2 );
	t.strictEqual( realf( v ), f32( 9.99 ), 'returns expected value' );
	t.strictEqual( imagf( v ), f32( 9.99 ), 'returns expected value' );

	v = cfloornf( new Complex64( -9.99999, -9.99999 ), -2 );
	t.strictEqual( realf( v ), f32( -10.0 ), 'returns expected value' );
	t.strictEqual( imagf( v ), f32( -10.0 ), 'returns expected value' );

	v = cfloornf( new Complex64( 0.0, 0.0 ), 2 );
	t.strictEqual( realf( v ), 0.0, 'returns expected value' );
	t.strictEqual( imagf( v ), 0.0, 'returns expected value' );

	t.end();
});

tape( 'rounding components to a desired number of decimals can result in unexpected behavior', function test( t ) {
	var x;
	var v;

	x = f32( f32( -0.2 ) - f32( 0.1 ) ); // returns -0.30000001192092896
	v = cfloornf( new Complex64( x, x ), -8 );
	t.strictEqual( realf( v ), f32( -0.30000000 ), 'returns expected value' );
	t.strictEqual( imagf( v ), f32( -0.30000000 ), 'returns expected value' );
	t.end();
});

tape( 'the function supports rounding components to a desired number of digits', function test( t ) {
	var v;

	v = cfloornf( new Complex64( -1234.0, 1234.0 ), 2 );
	t.strictEqual( realf( v ), -1300.0, 'returns expected value' );
	t.strictEqual( imagf( v ), 1200.0, 'returns expected value' );

	v = cfloornf( new Complex64( 12363.0, -12373.0 ), 1 );
	t.strictEqual( realf( v ), 12360.0, 'returns expected value' );
	t.strictEqual( imagf( v ), -12380.0, 'returns expected value' );

	t.end();
});

tape( 'the function returns the components unchanged if provided an `n` which is less than the minimum decimal exponential (-45)', function test( t ) {
	var exp;
	var n;
	var x;
	var v;
	var i;
	for ( i = 0; i < 100; i++ ) {
		exp = roundf( randu()*76.0 ) - 38;
		x = f32( (1.0+randu()) * powf( 10.0, exp ) );
		n = -(roundf( randu()*100.0 ) + 46);
		v = cfloornf( new Complex64( x, x ), n );
		t.strictEqual( realf( v ), x, 'returns expected value' );
		t.strictEqual( imagf( v ), x, 'returns expected value' );
	}
	t.end();
});

tape( 'if a component is too large a float to have decimals and `n < 0`, the component is returned unchanged', function test( t ) {
	var sign;
	var exp;
	var x;
	var n;
	var v;
	var i;
	for ( i = 0; i < 100; i++ ) {
		sign = ( randu()<0.5 ) ? -1.0 : 1.0;
		exp = 8 + roundf( randu()*30.0 );
		x = f32( sign * (1.0+randu()) * powf( 10.0, exp ) );
		n = -( roundf( randu()*38.0) );
		v = cfloornf( new Complex64( x, x ), n );
		t.strictEqual( realf( v ), x, 'returns expected value' );
		t.strictEqual( imagf( v ), x, 'returns expected value' );
	}
	t.end();
});

tape( 'if `n > 38` and a component is less than zero, the function returns `-infinity`', function test( t ) {
	var exp;
	var x;
	var n;
	var v;
	var i;
	for ( i = 0; i < 100; i++ ) {
		exp = roundf( randu()*37.0 );
		x = f32( -(1.0+randu()) * powf( 10.0, exp ) );
		n = roundf( randu()*10.0 ) + 39;
		v = cfloornf( new Complex64( x, x ), n );
		t.strictEqual( realf( v ), NINF, 'returns expected value' );
		t.strictEqual( imagf( v ), NINF, 'returns expected value' );
	}
	t.end();
});

tape( 'if `n > 38` and a component is greater than or equal to zero, the function returns `+0` (sign preserving)', function test( t ) {
	var exp;
	var x;
	var n;
	var v;
	var i;
	for ( i = 0; i < 100; i++ ) {
		exp = roundf( randu()*37.0 );
		x = f32( (1.0+randu()) * powf( 10.0, exp ) );
		n = roundf( randu()*10.0 ) + 39;
		v = cfloornf( new Complex64( x, x ), n );
		t.strictEqual( isPositiveZerof( realf( v ) ), true, 'returns expected value' );
		t.strictEqual( isPositiveZerof( imagf( v ) ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function supports rounding very small numbers (including subnormals)', function test( t ) {
	var expected;
	var x;
	var n;
	var v;
	var i;

	x = f32( f32( 3.1468234343023397 ) * powf( f32( 10.0 ), -38 ) );

	n = [];
	for ( i = -38; i > -46; i-- ) {
		n.push( i );
	}
	expected = [
		f32( 3.0e-38 ),
		f32( 3.1e-38 ),
		f32( 3.14e-38 ),
		f32( 3.146e-38 ),
		f32( 3.1468e-38 ),
		f32( 3.14682e-38 ),
		f32( 3.146823e-38 ),
		f32( 3.1468234e-38 )
	];

	for ( i = 0; i < n.length; i++ ) {
		v = cfloornf( new Complex64( x, x ), n[ i ] );
		t.strictEqual( isAlmostSameValuef( realf( v ), expected[ i ], 1 ), true, 'returns expected value' );
		t.strictEqual( isAlmostSameValuef( imagf( v ), expected[ i ], 1 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'if the function encounters overflow, the function returns the input component', function test( t ) {
	var x;
	var v;

	x = f32( 3.14 );
	v = cfloornf( new Complex64( x, x ), -46 );
	t.strictEqual( realf( v ), x, 'returns expected value' );
	t.strictEqual( imagf( v ), x, 'returns expected value' );

	x = f32( -3.14 );
	v = cfloornf( new Complex64( x, x ), -46 );
	t.strictEqual( realf( v ), x, 'returns expected value' );
	t.strictEqual( imagf( v ), x, 'returns expected value' );

	x = f32( 16777216.0 );
	v = cfloornf( new Complex64( x, x ), -40 );
	t.strictEqual( realf( v ), x, 'returns expected value' );
	t.strictEqual( imagf( v ), x, 'returns expected value' );

	x = f32( -16777216.0 );
	v = cfloornf( new Complex64( x, x ), -40 );
	t.strictEqual( realf( v ), x, 'returns expected value' );
	t.strictEqual( imagf( v ), x, 'returns expected value' );

	t.end();
});
